    .example {
      padding: 1.1rem 1.2rem;
      border: 1px solid var(--color-border);
      border-radius: 1rem;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02)),
