            What does a cat's tail say about its mood?
            <svg class="chevron" viewBox="0 0 16 16" aria-hidden="true" focusable="false">
              <path d="M3.25 5.75 8 10.25l4.75-4.5" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.75"></path>
            </svg>
          </button>
        </h2>
        <div class="details" id="answer-tail">
          <p>A relaxed upright tail usually signals confidence or a friendly greeting, while a puffed-up tail can mean fear or alarm.</p>
          <p>Fast tail flicking often suggests irritation or overstimulation, especially during play or petting.</p>
        </div>
      </div>
    </main>
  </div>

  <script>
    const faqButtons = document.querySelectorAll('.faq-trigger');

    function setExpanded(button, expanded) {
      const details = document.getElementById(button.getAttribute('aria-controls'));
      button.setAttribute('aria-expanded', String(expanded));
      details.hidden = !expanded;
    }

    faqButtons.forEach((button) => {
      setExpanded(button, false);

      button.addEventListener('click', () => {
        const expanded = button.getAttribute('aria-expanded') === 'true';
        setExpanded(button, !expanded);
      });

      button.addEventListener('keydown', (event) => {
        if (event.key === 'Escape' && button.getAttribute('aria-expanded') === 'true') {
          setExpanded(button, false);
          button.focus();
        }
      });
    });
  </script>
