const { chromium } = require('playwright');
const axeSource = require('axe-core').source;

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const audit = async (name) => {
    await page.addScriptTag({ content: axeSource });
    const results = await page.evaluate(async () => await window.axe.run(document, {
      runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21aa', 'wcag22aa', 'best-practice'] }
    }));
    return {
      name,
      wcag: results.violations
        .filter((v) => !v.tags.includes('best-practice'))
        .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      bp: results.violations
        .filter((v) => v.tags.includes('best-practice'))
        .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
    };
  };

  await page.setContent(html, { waitUntil: 'load' });
  const collapsed = await audit('collapsed');

  await page.reload({ waitUntil: 'load' });
  await page.setContent(html, { waitUntil: 'load' });
  await page.locator('.faq-trigger').first().focus();
  const count = await page.locator('.faq-trigger').count();
  for (let i = 0; i < count; i += 1) {
    await page.locator('.faq-trigger').nth(i).click();
  }
  const expanded = await audit('expanded');

  await browser.close();
  const output = { collapsed, expanded };
  console.log(JSON.stringify(output, null, 2));
  const hasFailures = output.collapsed.wcag.length || output.expanded.wcag.length;
  process.exit(hasFailures ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
NODE

